import path from 'node:path';
import * as sentry from '@sentry/node-core/light';
// export this function for testing.
export const truncateFailureMessage = (message) => {
    if (typeof message !== 'string') {
        return;
    }
    const ln = message.search(/$/m);
    if (ln > 0 && message.length !== ln) {
        return message.slice(0, ln) + '\n(truncated...)';
    }
    else {
        return message;
    }
};
export const sendFlakyTestCasesToSentry = (flakyTestCases, context, flakyTestCasesInRetries = []) => {
    const tags = Object.fromEntries(context.tags.map((tag) => {
        const key = tag.split(':')[0];
        const value = tag.split(':').slice(1).join(':');
        return [key, value];
    }));
    const flakyTestCasesWithKindTags = [
        ...flakyTestCases.map((testCase) => ({ testCase, flakyKindTags: {} })),
        ...flakyTestCasesInRetries.map((testCase) => ({ testCase, flakyKindTags: { 'testcase.flaky_kind': 'retry' } })),
    ];
    for (const { testCase, flakyKindTags } of flakyTestCasesWithKindTags) {
        const testFilePath = path.join(context.testCaseBaseDirectory, testCase.filename);
        const event = {
            message: testCase.name,
            fingerprint: [testFilePath, testCase.name],
            tags: {
                ...tags,
                'testcase.owners': testCase.owners.join(','),
                'testcase.filename': testCase.filename,
                ...flakyKindTags,
            },
            exception: {
                values: [
                    {
                        module: testFilePath,
                        type: testCase.name,
                        value: truncateFailureMessage(testCase.failureMessage),
                        stacktrace: {
                            frames: [
                                {
                                    filename: testFilePath,
                                    function: testCase.name,
                                    in_app: true,
                                },
                            ],
                        },
                    },
                ],
            },
            breadcrumbs: [],
        };
        sentry.captureEvent(event);
    }
};
