import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import * as core from '@actions/core';
import { Minimatch } from 'minimatch';
// Parse the CODEOWNERS and return the records in order.
export const parse = (content) => {
    const rules = [];
    const lines = content.split(/[\r\n]+/);
    for (const line of lines) {
        const owners = line
            .replace(/#.+$/, '')
            .split(/\s+/)
            .filter((s) => s !== '');
        const pattern = owners.shift();
        if (!pattern) {
            continue;
        }
        rules.push({ pattern, owners });
    }
    return rules;
};
const compile = (rule) => {
    let pattern = rule.pattern;
    if (pattern.startsWith('**')) {
        pattern = `/${pattern}`;
    }
    else if (!pattern.startsWith('/')) {
        pattern = `/**/${pattern}`;
    }
    if (pattern.endsWith('/')) {
        pattern = `${pattern}**`;
    }
    const m = new Minimatch(pattern, {
        dot: true,
        nobrace: true,
        nocomment: true,
        noext: true,
        nonegate: true,
    });
    return {
        match: (filename) => {
            if (!filename.startsWith('/')) {
                filename = `/${filename}`;
            }
            return m.match(filename);
        },
        owners: rule.owners,
    };
};
export class Matcher {
    ruleMatchers;
    constructor(rules) {
        this.ruleMatchers = rules
            .map((rule) => compile(rule))
            // We need to find one in reverse order. The last mentioned code owner is valid.
            // https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-code-owners#codeowners-syntax
            .reverse();
    }
    findOwners(filename) {
        for (const ruleMatcher of this.ruleMatchers) {
            if (ruleMatcher.match(filename)) {
                return ruleMatcher.owners;
            }
        }
        return [];
    }
}
export const createMatcher = (codeownersContent) => new Matcher(parse(codeownersContent));
export const createFinder = async (baseDirectory) => {
    const tryAccess = async (path) => {
        try {
            await fs.access(path);
            return path;
        }
        catch {
            return null;
        }
    };
    // https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-code-owners#codeowners-file-location
    const codeowners = (await tryAccess('.github/CODEOWNERS')) ?? (await tryAccess('CODEOWNERS')) ?? (await tryAccess('docs/CODEOWNERS'));
    if (!codeowners) {
        return () => [];
    }
    core.info(`Parsing ${codeowners}`);
    const matcher = createMatcher(await fs.readFile(codeowners, 'utf8'));
    return (filename) => {
        const canonicalPath = path.join(baseDirectory, filename);
        return matcher.findOwners(canonicalPath).map((owner) => owner.replace(/^@.+?\/|^@/, '')); // Remove leading @organization/
    };
};
