export const getTestReportMetrics = (testReport, flakyTestCases, context, flakyTestCasesInRetries = []) => {
    return joinMetrics(...testReport.testFiles.map((testFile) => getTestFileMetrics(testFile, context)), ...testReport.testCases.map((testCase) => getTestCaseMetrics(testCase, context)), ...flakyTestCases.map((testCase) => getFlakyTestCaseMetrics(testCase, context, [])), ...flakyTestCasesInRetries.map((testCase) => getFlakyTestCaseMetrics(testCase, context, ['flaky_kind:retry'])));
};
const getTestFileMetrics = (testFile, context) => {
    const tags = [
        ...context.tags,
        `testfile_name:${testFile.filename}`,
        ...testFile.owners.map((owner) => `testfile_owner:${owner}`),
    ];
    const metrics = {
        series: [],
        distributionPointsSeries: [],
    };
    const duration = testFile.totalTime;
    if (duration > context.filterTestFileSlowerThan) {
        metrics.distributionPointsSeries.push({
            metric: `${context.prefix}.testfile.duration`,
            points: [[context.timestamp, [duration]]],
            tags,
        });
    }
    return metrics;
};
const getTestCaseMetrics = (testCase, context) => {
    const tags = [
        ...context.tags,
        `testcase_name:${testCase.name}`,
        `testcase_file:${testCase.filename}`,
        ...testCase.owners.map((owner) => `testcase_owner:${owner}`),
    ];
    const metrics = {
        series: [],
        distributionPointsSeries: [],
    };
    if (testCase.success) {
        if (context.sendTestCaseSuccess) {
            metrics.series.push({
                metric: `${context.prefix}.testcase.success_count`,
                points: [[context.timestamp, 1]],
                type: 'count',
                tags,
            });
        }
    }
    else {
        if (context.sendTestCaseFailure) {
            metrics.series.push({
                metric: `${context.prefix}.testcase.failure_count`,
                points: [[context.timestamp, 1]],
                type: 'count',
                tags,
            });
        }
    }
    const duration = testCase.time;
    if (duration > context.filterTestCaseSlowerThan) {
        metrics.distributionPointsSeries.push({
            metric: `${context.prefix}.testcase.duration`,
            points: [[context.timestamp, [duration]]],
            tags,
        });
    }
    return metrics;
};
const getFlakyTestCaseMetrics = (testCase, context, flakyKindTags) => {
    const tags = [
        ...context.tags,
        `testcase_name:${testCase.name}`,
        `testcase_file:${testCase.filename}`,
        ...testCase.owners.map((owner) => `testcase_owner:${owner}`),
        ...flakyKindTags,
    ];
    const metrics = {
        series: [],
        distributionPointsSeries: [],
    };
    metrics.series.push({
        metric: `${context.prefix}.testcase.flaky_failure_count`,
        points: [[context.timestamp, 1]],
        type: 'count',
        tags,
    });
    return metrics;
};
const joinMetrics = (...metricsArray) => {
    const joined = {
        series: [],
        distributionPointsSeries: [],
    };
    for (const metrics of metricsArray) {
        joined.series.push(...metrics.series);
        joined.distributionPointsSeries.push(...metrics.distributionPointsSeries);
    }
    return joined;
};
